function loadPricingData() {
  const file = path.join(PUBLIC, "data", "verifiedPricing.json");
  if (!fs.existsSync(file)) return defaultPricing;
  try {
    const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
    if (!Array.isArray(parsed.models) || parsed.models.length === 0) return defaultPricing;
    return { ...defaultPricing, ...parsed, last_verified: parsed.last_verified || TODAY };
  } catch {
    return defaultPricing;
  }
}

