function sourceTable(models = pricing.models) {
  const money = (m, value) => {
    if (value === null || value === undefined) return "Not listed";
    const symbol = m.currency === "CNY" ? "¥" : "$";
    return `${symbol}${value}`;
  };
  return `<table><thead><tr><th>Provider</th><th>Model</th><th>Input / 1M</th><th>Cached input / 1M</th><th>Output / 1M</th><th>Currency</th><th>Last verified</th><th>Source</th></tr></thead><tbody>${models.map(m => `<tr><td>${m.provider}</td><td>${m.model}</td><td>${money(m, m.input_per_1m)}</td><td>${money(m, m.cached_input_per_1m)}</td><td>${money(m, m.output_per_1m)}</td><td>${m.currency}</td><td>${m.last_verified || pricing.last_verified}</td><td><a href="${m.source_url}">source</a></td></tr>`).join("")}</tbody></table>`;
}

function cost(model, volume, input, output, cache = 0, retries = 0) {
  const normalInput = input * (1 - cache);
  const cachedInput = input * cache;
  const per = (normalInput / 1e6) * model.input_per_1m + (cachedInput / 1e6) * (model.cached_input_per_1m ?? model.input_per_1m) + (output / 1e6) * model.output_per_1m;
  return per * volume * (1 + retries);
}

function scenarioRows(models, scenarios) {
  const usdModels = models.filter(m => m.currency === "USD");
  return scenarios.map(s => `<h3>${s.name}</h3><p class="muted">Assumptions: ${s.volume.toLocaleString()} requests/month, ${s.input.toLocaleString()} input tokens, ${s.output.toLocaleString()} output tokens, ${Math.round(s.cache*100)}% cacheable input, ${Math.round(s.retries*100)}% retry overhead. Scenario tables calculate USD rows only to avoid unsourced currency conversion.</p><table><thead><tr><th>Model</th><th>Monthly estimate</th><th>Annualized</th><th>Input/output driver</th></tr></thead><tbody>${usdModels.map(m => { const v=cost(m,s.volume,s.input,s.output,s.cache,s.retries); return `<tr><td>${m.provider} ${m.model}</td><td>$${v.toFixed(2)}</td><td>$${(v*12).toFixed(2)}</td><td>${s.output * m.output_per_1m > s.input * m.input_per_1m ? "Output-heavy" : "Input-heavy"}</td></tr>`; }).join("")}</tbody></table>`).join("");
}

